    question: '五臓の特徴的な症状と治療穴の組合せで正しいのはどれか。',
    choices: ['五更泄瀉─太衝', '梅核気─太淵', '陽萎─大陵', '多夢─神門'],
    answer: 3,
    explanation: '五更泄瀉は早朝、夜明け前、午前3〜5時（五更の刻）に下痢をするので鶏鳴下痢ともいう。脾腎陽虚でみられ、温煦機能の低下によって全身性の冷え、脾の運化機能の低下となる。太衝は肝なので該当しない。梅核気は咽喉部に梅の核のようなものが詰まった感覚があるもので、肝気鬱結で気機の疏通や拡散の機能が低下し痰気が喉を阻むことで起きる。ヒステリー球ともいう。太淵は肺なので該当しない。陽萎は腎精不足、腎陽虚でみられる。大陵は心包なので該当しない。多夢は心気虚、心血虚、心陰虚など心の病証に広くみられる。神門は心であり、4が正解である。',
    tags: ['多夢', '神門', '心の病証'],
