    explanation: '過敏性腸症候群（IBS）では器質的疾患はなく、腸管の機能異常による腹痛・腹部不快感とそれに関連した便通異常がみられる。消化管運動異常とともに消化管の知覚過敏・知覚閾値低下がみられる。よって知覚閾値の上昇は誤り。設問の症例は下痢型のIBSと考えられる。IBSの病態にはストレスが関与し、ストレス負荷と消化器症状悪化が相関する（腸脳相関）。視床下部から放出される副腎皮質刺激ホルモン放出ホルモン（CRH）は腸の運動を亢進させる。よって消化管運動の亢進が正答となる。IBSは自律神経反応に異常がみられ、交感神経活動の増加による腸管の運動抑制もみとめられるが、この症例では下痢型であるので、副交感神経の亢進が考えられ、交感神経機能亢進は誤りである。',
